//#region src/middleware/backward-compatibility-0-0-57.d.ts
/**
 * Client middleware that removes subagent-support additions when the REMOTE AGENT is
 * pre-subagent (its `maxProtocolVersion` <= 0.0.57; the shim is auto-inserted by that gate).
 * The old party is the upstream agent, not the downstream consumer (the current client
 * supports subagents).
 *
 *  - client → agent (the run input): strips `subagentRunId` from every top-level message so
 *    a pre-subagent agent never receives attribution it doesn't understand. This is the
 *    load-bearing half — the client's replayed message history can carry `subagentRunId`,
 *    and this is what protects the old agent from it.
 *  - agent → client (the event stream): defensive normalization. A genuinely pre-subagent
 *    agent cannot emit `SUBAGENT_*` events or `subagentRunId`, and any `RUN_STARTED.input`
 *    echo was already sanitized on the way in — so this path guards mixed/proxied
 *    pipelines rather than doing load-bearing translation. It drops
 *    SUBAGENT_STARTED/FINISHED/ERROR events and strips `subagentRunId` from every remaining
 *    event, from MESSAGES_SNAPSHOT messages, and from RUN_STARTED `input` messages.
 *
 * Scope: this removes the protocol-level `subagentRunId` field and the SUBAGENT_* event
 * types only. It does NOT recurse into opaque application payloads (`RAW.event`,
 * `CUSTOM.value`, `STATE_SNAPSHOT.snapshot`, `STATE_DELTA.delta`, activity `content`,
 * etc.). Non-lifecycle events a subagent produced (TEXT_MESSAGE_*, TOOL_CALL_*, ...) are
 * kept with their `subagentRunId` stripped, so they flatten into the parent thread — the
 * intended downgrade, since subagent separation cannot be represented to a consumer with
 * no concept of it.
 *
 * The subagent feature is purely additive, so this shim is a pure removal in both
 * directions; there is no field/event to translate (unlike 0.0.45's THINKING->REASONING).
 *
 * Who this actually fires for: `maxProtocolVersion` defaults to this library's own
 * version, which sits above every era threshold, so the shim is installed only for an
 * agent subclass that OVERRIDES the ceiling to declare an older backend. As of this
 * writing exactly ONE integration in this repository does:
 * `integrations/community/spring-ai/typescript/src/index.ts`, pinned at 0.0.39.
 *
 * An earlier version of this note claimed six, naming llama-index, pydantic-ai, ag2,
 * agno and crew-ai alongside it. That census was wrong, and three of those integrations
 * now carry tests asserting the opposite -- llama-index's `multimodal-passthrough`,
 * and crew-ai's and agno's `no-content-flattening`, each of which fails if the agent
 * starts pinning a ceiling again. Do not trust this paragraph either: it is a snapshot
 * of code that lives outside this package and nothing keeps it honest. Re-check with
 * `grep -rn "maxProtocolVersion\|maxVersion" integrations` before relying on it.
 *
 * Where the shim IS installed, the client → agent strip carries the weight: those
 * backends predate subagents, so a replayed history or a stored thread written by a
 * newer client must not deliver them attribution they cannot interpret. The
 * agent → client strip is the defensive counterpart described above.
 */
declare class BackwardCompatibility_0_0_57 extends Middleware {
  private warnDroppedLifecycleEvent;
  run(input: RunAgentInput, next: AbstractAgent): Observable<BaseEvent>;
}
//#endregion
//#region src/middleware/compatibility-boundary.d.ts
/**
 * The always-on pre-1.0 compatibility boundary.
 *
 * With enforcement running AFTER middleware (PNI-205), anything nobody
 * translates is stripped with a warning. This middleware is the translator:
 * it upgrades every retired-but-understood inbound shape into its 1.0
 * equivalent, so no data an old peer sends is lost. It is deliberately NOT
 * version-gated — a legacy-shaped event arriving is itself the proof the
 * peer is old, and on a modern stream every branch below is a no-op.
 * Outgoing legacy binary attachments are also upgraded before the transport
 * validates or sends them. Their shape identifies the conversion regardless
 * of the peer ceiling; actual downgrades remain version-gated separately.
 *
 * Inbound conversions, each warned once per occurrence with a pointer to
 * the repo-root DEPRECATIONS.md:
 * - THINKING_* events -> their REASONING_* equivalents. The version-gated
 *   BackwardCompatibility_0_0_45 runs the same state machine and keeps its
 *   0.0.45 threshold, but it is not untouched: its synthesized
 *   REASONING_MESSAGE_START now says `role: "reasoning"` where it used to say
 *   "assistant", the same correction made here, because enforcement moved
 *   behind the middleware chain and made the invalid role fatal. In practice
 *   only this translation runs: THIS middleware is appended innermost, so it
 *   sees every thinking event first and the shim always finds nothing to do
 *   (see the corpus README's "A shim with no fixture").
 * - Legacy binary content parts inside inbound messages (MESSAGES_SNAPSHOT,
 *   RUN_STARTED input) -> the modern media parts.
 * - The three legacy nulls -> absent: parentMessageId on TOOL_CALL_START and
 *   TOOL_CALL_CHUNK, and RUN_FINISHED.outcome.
 * - Optional JSON payload nulls accepted before 1.0 -> absent: rawEvent,
 *   run/subagent result, media-part metadata, and optional JSON request fields
 *   inside RUN_STARTED.input. Required and nested data nulls survive.
 */
declare class CompatibilityBoundary extends Middleware {
  private currentReasoningId;
  private currentMessageId;
  private warn;
  /**
   * A THINKING_* continuation names nothing: the id it belongs to lives in
   * this middleware's state, put there by the matching opener. When no opener
   * preceded it, there is no id to reuse and one is MINTED — which turns a
   * producer's "content with no start" into a REASONING_* event naming an id
   * nothing ever opened. Verification rejects that a few stages later, with a
   * message about an id no producer ever wrote, so the mint is announced here:
   * without this line the rejection is untraceable to its cause.
   */
  private mintedContinuationId;
  /**
   * A conversion side effect the caller has to be told about in its own
   * sentence: something lost, or something invented. Separate from `warn`,
   * which only announces that a retired shape was translated — a reader who
   * saw only that would have no way to know the translation was not
   * information-preserving.
   */
  private warnAside;
  run(input: RunAgentInput, next: AbstractAgent): Observable<BaseEvent>;
  private transformEvent;
  private upgradeInboundMessage;
}
//#endregion
